const openPermissionItem = async () => {
	const itemTypeName = 'Permission';
	const itemType = await ArasModules.metadata.itemType.getItemType(itemTypeName);
	const permissionId = ArasModules.xml.selectSingleNode(window.item, 'permission_id').text;
	const itemNode = aras.getItemById(itemTypeName, permissionId, 0);
	const { commandFactory } = options;
	const commandOptions = { itemTypeName, itemType, itemNode };
	const openItemCommand = commandFactory('OpenItem', commandOptions);
	return openItemCommand.execute();
};

return openPermissionItem();
